<?php require_once '../includes/db.php';require_once '../includes/functions.php';admin_required();$title='Dashboard';$adminPage=true;$stats=['products'=>$conn->query("SELECT COUNT(*) n FROM products")->fetch_assoc()['n'],'orders'=>$conn->query("SELECT COUNT(*) n FROM orders")->fetch_assoc()['n'],'new'=>$conn->query("SELECT COUNT(*) n FROM orders WHERE status='Placed'")->fetch_assoc()['n'],'sales'=>$conn->query("SELECT COALESCE(SUM(total),0) n FROM orders WHERE status<>'Cancelled'")->fetch_assoc()['n']];$orders=$conn->query("SELECT * FROM orders ORDER BY id DESC LIMIT 8")->fetch_all(MYSQLI_ASSOC);include '../includes/header.php';?><div class="heading"><div><small>STORE OVERVIEW</small><h2>Dashboard</h2><p>Welcome, <?=e($_SESSION['admin_name']??'Admin')?>.</p></div><a class="btn dark" href="products.php">Manage products →</a></div><div class="stats"><?php foreach(['Products'=>$stats['products'],'Orders'=>$stats['orders'],'New orders'=>$stats['new'],'Recorded sales'=>'₹'.number_format($stats['sales'],2)] as $k=>$v):?><div class="stat"><small><?=e($k)?></small><b><?=e($v)?></b></div><?php endforeach;?></div><div class="panel"><div class="heading"><h2>Recent orders</h2><a href="orders.php">All orders →</a></div><div class="scroll"><table><tr><th>Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['customer_name'])?></td><td><?=e(date('d M Y',strtotime($o['created_at'])))?></td><td>₹<?=number_format($o['total'],2)?></td><td><?=e($o['status'])?></td></tr><?php endforeach;?></table></div></div><?php include '../includes/footer.php';?>